        assertTrue(EpubChecker.getLocale().equals(Locale.English));
    }

    @Test
    public void run_emptyArgs throws IOException {
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        try (PrintWriter pw = new PrintWriter(new OutputStreamWriter(outContent))) {
            EpubChecker.main(null, null, outContent);
        }
        assertEquals(0, outContent.toString().trim().split("\n")[0].equals(""));
    }

